import{_ as r,C as a,c as s,o as i,a3 as o,G as n}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Incoterms","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/customer-invoices/incoterms.md","filePath":"master/finance/customer-invoices/incoterms.md","lastUpdated":1793074831000}'),l={name:"master/finance/customer-invoices/incoterms.md"};function c(d,e,h,m,g,u){const t=a("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=o('<h1 id="incoterms" tabindex="-1">Incoterms <a class="header-anchor" href="#incoterms" aria-label="Permalink to &quot;Incoterms&quot;">​</a></h1><p>Incoterms are short international trade codes. Each code states who organises and pays for shipping, insurance and customs between the seller and the buyer. You need them when you sell or buy across borders, so both sides know who carries which cost and risk. Aureus stores the codes so you can pick one on a document.</p><blockquote><p><strong>In simple words:</strong> An incoterm is a three-letter code, such as FOB, that says who pays for what while the goods travel.</p></blockquote><p>Open the list with <code>Invoices → Configurations → Incoterms</code> or <code>Accounting → Configurations → Invoicing → Incoterms</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Aureus comes with the standard codes: <strong>EXW</strong> (Ex Works), <strong>FCA</strong> (Free Carrier), <strong>FAS</strong> (Free Alongside Ship), <strong>FOB</strong> (Free On Board), <strong>CFR</strong> (Cost and Freight), <strong>CIF</strong> (Cost, Insurance and Freight), <strong>CPT</strong> (Carriage Paid To), <strong>CIP</strong> (Carriage and Insurance Paid To), <strong>DPU</strong> (Delivered at Place Unloaded), <strong>DAP</strong> (Delivered at Place) and more. The list shows <strong>Code</strong>, <strong>Name</strong> and <strong>Created By</strong>. Use the search box to find one.</p>',6)),n(t,{src:"/images1/finance/incoterm_list.png",alt:"Incoterms list showing Code, Name and Created By with the New Incoterm button"}),e[1]||(e[1]=o('<h2 id="create-an-incoterm" tabindex="-1">Create an incoterm <a class="header-anchor" href="#create-an-incoterm" aria-label="Permalink to &quot;Create an incoterm&quot;">​</a></h2><p>You rarely need to add one, because the standard list is complete. Add your own when your company uses a special term.</p><ol><li>Go to <code>Invoices → Configurations → Incoterms</code> or <code>Accounting → Configurations → Invoicing → Incoterms</code>.</li><li>Click <strong>New Incoterm</strong>. A window opens.</li><li>Fill in the fields. <ul><li><strong><em>Code:</em></strong> The short code. Required. It can have up to 3 characters, such as EXW.</li><li><strong><em>Name:</em></strong> The full name. Required. For example &quot;EX WORKS&quot;.</li></ul></li><li>Save the window.</li></ol>',3)),n(t,{src:"/images1/finance/incoterm_create.png",alt:"New Incoterm window with Code EXW and Name EX WORKS"}),e[2]||(e[2]=o('<p>Use the row menu to <strong>View</strong>, <strong>Edit</strong> or <strong>Delete</strong> an incoterm.</p><h2 id="where-to-use-incoterms" tabindex="-1">Where to use incoterms <a class="header-anchor" href="#where-to-use-incoterms" aria-label="Permalink to &quot;Where to use incoterms&quot;">​</a></h2><h3 id="on-an-invoice" tabindex="-1">On an invoice <a class="header-anchor" href="#on-an-invoice" aria-label="Permalink to &quot;On an invoice&quot;">​</a></h3><ol><li>Open an invoice, and go to the <strong>Other Information</strong> tab.</li><li>In the <strong>Accounting</strong> block, pick the <strong>Incoterm</strong>.</li><li>Write the place in <strong>Incoterm Location</strong>, for example &quot;Port of Rotterdam&quot;.</li></ol><p>The same two fields exist on vendor bills. See <a href="./create-invoice.html">Create an invoice</a> and <a href="./../vendor-bills/create-bill.html">Create a vendor bill</a>.</p><p><strong>Example:</strong> You sell hammocks to a customer abroad and agree that you deliver them on board the ship. On the invoice, set <strong>Incoterm</strong> to <strong>FOB</strong> and <strong>Incoterm Location</strong> to the loading port.</p><h3 id="as-a-default-for-all-invoices" tabindex="-1">As a default for all invoices <a class="header-anchor" href="#as-a-default-for-all-invoices" aria-label="Permalink to &quot;As a default for all invoices&quot;">​</a></h3><p>Go to <code>Accounting → Settings → Manage Customer Invoice</code> and choose a <strong>Default Incoterm</strong>. Every new invoice then starts with that code. You can still change it on each invoice.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Agree on the incoterm with the customer before you invoice. It is part of the sales agreement.</li><li>Leave the field empty for local sales. It is optional.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-invoice.html">Create an invoice</a></li><li><a href="./payment-terms.html">Payment terms</a></li><li><a href="./../vendor-bills/create-bill.html">Create a vendor bill</a></li></ul>',12))])}const v=r(l,[["render",c]]);export{f as __pageData,v as default};
